import { Link } from 'react-router-dom'
import { useSelector } from 'react-redux'
import { HeaderBar } from './styles'
import logo from '../../../assets/images.nova/logo.svg'
import { LinkCart } from '../styles'
import { RootState } from '../../store/store'

const HeaderAlternativo = () => {
  // Acessa os itens no carrinho no estado global
  const itensNoCarrinho = useSelector((state: RootState) => state.carrinho.itens)

  return (
    <HeaderBar>
      <div>
        <h3>Restaurante</h3>
        <Link to="/">
          <img src={logo} alt="eFood" />
        </Link>
        <LinkCart to="/carrinho"> {/* Link para a página do carrinho */}
          <p>{itensNoCarrinho.length} - produto(s)</p> {/* Exibe o número de produtos */}
        </LinkCart>
      </div>
    </HeaderBar>
  )
}

export default HeaderAlternativo
